package report

import (
	"embed"
	"fmt"
)

const DefaultHTMLTemplate = "review-summary"
const multiSeverityNotCollectedInstruction = "summary.findings_by_severity.not_collected \u8868\u793a\u4e25\u91cd\u7b49\u7ea7\u672a\u91c7\u96c6\u7684\u95ee\u9898\u8bb0\u5f55\u6570\uff0c\u4f7f\u7528\u56fa\u5b9a\u6807\u7b7e \u672a\u63d0\u4f9b\u7b49\u7ea7\u6570\u91cf \u5355\u72ec\u663e\u793a\uff0c\u4e0d\u5f97\u8ba1\u5165\u56db\u4e2a\u5df2\u77e5\u4e25\u91cd\u7b49\u7ea7\u6216\u5f53\u6210\u96f6\u3002"

//go:embed templates/review-summary.md
var htmlTemplates embed.FS

func HTMLTemplate(name string) (string, error) {
	if name != DefaultHTMLTemplate {
		return "", fmt.Errorf("unknown report template %q", name)
	}
	content, err := htmlTemplates.ReadFile("templates/review-summary.md")
	if err != nil {
		return "", fmt.Errorf("load report template %q: %w", name, err)
	}
	return string(content), nil
}

func MultiHTMLTemplate(name string) (string, error) {
	content, err := HTMLTemplate(name)
	if err != nil {
		return "", err
	}
	content += "\n\n" + multiSeverityNotCollectedInstruction
	return content + "\n\n## \u591a\u5ba1\u67e5\u5355\u5143\u8981\u6c42\n\n\u672c\u6b21\u8f93\u5165\u5305\u542b\u591a\u4efd\u6750\u6599\uff1b\u4ee5\u4e0b\u591a\u5355\u5143\u7ed3\u6784\u8986\u76d6\u4e0a\u6587\u7684\u5355\u4efd main \u6807\u8bc6\u548c\u4e8b\u5b9e\u8def\u5f84\u8981\u6c42\u3002\u6309\u7528\u6237\u8f93\u5165\u987a\u5e8f\u4fdd\u7559\u6bcf\u4e2a\u5ba1\u67e5\u5355\u5143\uff0c\u4f7f\u7528\u552f\u4e00\u7684\u6750\u6599 run_id \u533a\u5206\u5b83\u4eec\u3002main \u4f7f\u7528 data-report-kind=\"multi-unit\" \u548c\u4e0e\u8f93\u5165\u6570\u76f8\u7b26\u7684 data-review-unit-count\uff0c\u4e0d\u4f7f\u7528\u5355\u4e2a data-review-status \u6216 data-run-id\u3002\n\n\u6bcf\u4e2a\u5fc5\u9700\u7ae0\u8282\u90fd\u6309\u8f93\u5165\u987a\u5e8f\u63d0\u4f9b\u4e00\u4e2a\u76f4\u63a5 data-review-unit-id \u5206\u7ec4\u5bb9\u5668\uff1b\u5355\u5143 ID \u662f\u6750\u6599 run_id \u7684\u7a33\u5b9a\u6807\u8bc6\u3002overview \u4e2d\u6bcf\u4e2a\u5206\u7ec4\u4ee5\u8be5\u6750\u6599\u7684 review.run_id \u4e8b\u5b9e\u5f00\u5934\uff0c\u4f7f\u7528\u201c\u8fd0\u884c\u6807\u8bc6\u201d\u56fa\u5b9a\u6807\u7b7e\u4f5c\u4e3a\u5355\u5143\u6807\u5934\u3002\u6750\u6599\u4e8b\u5b9e\u8def\u5f84\u52a0\u4e0a review_units[\u5e8f\u53f7].material. \u524d\u7f00\u5e76\u653e\u5728\u5bf9\u5e94\u5bb9\u5668\u5185\u3002\u540c\u4e00\u5b57\u6bb5\u5141\u8bb8\u5728\u5b83\u7684\u6750\u6599\u5141\u8bb8\u7684\u591a\u4e2a\u7ae0\u8282\u4e2d\u91cd\u590d\uff0c\u4f46\u4e0d\u5f97\u5728\u540c\u4e00\u7ae0\u8282\u91cd\u590d\u3002\u6bcf\u4e2a\u95ee\u9898 article \u5fc5\u987b\u76f4\u63a5\u5e26 data-review-unit-id \u548c\u539f data-finding-id\uff0c\u4e14\u4f4d\u4e8e\u6240\u5c5e\u5355\u5143\u5bb9\u5668\u5185\uff1b\u4e0d\u540c\u5355\u5143\u5373\u4f7f\u95ee\u9898 ID \u76f8\u540c\u4e5f\u90fd\u8981\u5b8c\u6574\u4fdd\u7559\u3002\u6bcf\u5355\u5143\u7edf\u8ba1\u653e\u5728\u8be5\u5355\u5143\u5f52\u5c5e\u5bb9\u5668\u5185\uff0c\u4f7f\u7528\u5355\u4efd\u62a5\u544a\u89c4\u5b9a\u7684\u7edf\u8ba1\u540d\u79f0\u4e0e\u7cbe\u786e\u503c\u3002\n\nsummary \u7684\u4e8b\u5b9e\u4f7f\u7528 summary. \u8def\u5f84\uff0creview_unit_count\u3001finding_record_count \u548c finding_counting_rule \u653e\u5728 overview\uff1bfindings_by_severity \u653e\u5728 quality-coverage\u3002finding_record_count \u8868\u793a\u5ba1\u67e5\u5355\u5143\u5185\u95ee\u9898\u8bb0\u5f55\u4e4b\u548c\uff0c\u4e0d\u662f\u8de8\u4ed3\u5e93\u6216\u91cd\u53e0\u8303\u56f4\u7684\u552f\u4e00\u95ee\u9898\u6570\u3002people \u7684\u4e8b\u5b9e\u4f7f\u7528 people[\u5e8f\u53f7]. \u8def\u5f84\uff0c\u5217\u51fa\u786e\u5b9a\u8eab\u4efd\u3001\u4fdd\u7559\u7684\u540d\u79f0\u53d8\u4f53\u53ca\u9010\u5355\u5143\u8d21\u732e\u3002\u4e0d\u5f97\u4ec5\u6309\u59d3\u540d\u5408\u5e76\u8eab\u4efd\uff0c\u4e0d\u786e\u5b9a\u522b\u540d\u5e94\u4fdd\u6301\u72ec\u7acb\u3002\u4e0d\u5f97\u628a\u540c\u4ed3\u5e93\u91cd\u53e0\u8303\u56f4\u53bb\u91cd\u603b\u91cf\u5316\uff0c\u4e0d\u5f97\u4ece\u4e0d\u540c\u4ed3\u5e93\u95ee\u9898\u63a8\u65ad\u8de8\u4ed3\u5e93\u63a5\u53e3\u7f3a\u9677\u3002\n", nil
}
